package com.nexusdrive.common.security;
import com.nexusdrive.common.config.JwtProperties; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*; import javax.crypto.SecretKey;
public class JwtTokenProvider { private final JwtProperties p; private final SecretKey key; public JwtTokenProvider(JwtProperties p){this.p=p;if(p.getSecret()==null||p.getSecret().getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalArgumentException("JWT secret must be at least 32 bytes");key=Keys.hmacShaKeyFor(p.getSecret().getBytes(StandardCharsets.UTF_8));}
 public String generateAccessToken(UUID id,String username,String role){return token(id,username,role,p.getAccessExpirationMs(),"access");} public String generateRefreshToken(UUID id,String username,String role){return token(id,username,role,p.getRefreshExpirationMs(),"refresh");}
 private String token(UUID id,String username,String role,long ttl,String type){Instant n=Instant.now();return Jwts.builder().id(UUID.randomUUID().toString()).subject(username).claim("userId",id.toString()).claim("role",role).claim("type",type).issuedAt(Date.from(n)).expiration(Date.from(n.plusMillis(ttl))).signWith(key,Jwts.SIG.HS256).compact();}
 public Claims parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} public boolean validate(String token){try{parse(token);return true;}catch(JwtException|IllegalArgumentException e){return false;}} public UUID userId(String token){return UUID.fromString(parse(token).get("userId",String.class));} public String role(String token){return parse(token).get("role",String.class);} public long accessExpirationSeconds(){return p.getAccessExpirationMs()/1000;}
}
